import{_ as i,a0 as p,w as s,s as m,ao as n,I as o,x as t,a1 as l,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"怎樣通過示弱增強領導力 | LCTT x X-CMD","titleTemplate":false,"description":"怎樣通過示弱增強領導力 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣通過示弱增強領導力 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣通過示弱增強領導力 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20180104 How allowing myself to be vulnerable made me a better leader","title":"怎樣通過示弱增強領導力","tag":"201908","desc":""},"relativePath":"201908/20180104 How allowing myself to be vulnerable made me a better leader.md","filePath":"[post].md"}'),d={name:"201908/20180104 How allowing myself to be vulnerable made me a better leader.md"};function u(b,e,f,T,g,_){const a=p("Link");return s(),m("div",null,[e[16]||(e[16]=n('<h1 id="怎樣通過示弱增強領導力" tabindex="-1">怎樣通過示弱增強領導力 <a class="header-anchor" href="#怎樣通過示弱增強領導力" aria-label="Permalink to “怎樣通過示弱增強領導力”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201908/25/052430b01hc00qrcz99p9w.jpg" alt=""></p><p>傳統觀念中的領導者總是強壯、大膽、果決的。我也確實見過一些擁有這些特點的領導者。但更多時候，領導者也許看起來比傳統印象中的領導者要更脆弱些，他們內心有很多這樣的疑問：我的決策正確嗎？我真的適合這個職位嗎？我有沒有在做最該做的事情？</p><p>解決這些問題的方法是把問題説出來。把問題憋在心裏只會助長它們，一名開明的領導者更傾向於把自己的脆弱之處暴露出來，這樣我們才能從有過相同經驗的人那裏得到慰藉。</p><p>為了證明這個觀點，我來講一個故事。</p><h3 id="一個擾人的想法" tabindex="-1">一個擾人的想法 <a class="header-anchor" href="#一個擾人的想法" aria-label="Permalink to “一個擾人的想法”">​</a></h3>',6)),o("p",null,[e[1]||(e[1]=t("假如你在教育領域工作，你會發現發現大家更傾向於創造",-1)),l(a,{href:"https://opensource.com/open-organization/17/9/building-for-inclusivity"},{default:r(()=>[...e[0]||(e[0]=[t("一個包容性的環境",-1)])]),_:1}),e[2]||(e[2]=t(" —— 一個鼓勵多樣性繁榮發展的環境。長話短説，我一直以來都認為自己是出於營造包容性環境的考量，而進行的“多樣性僱傭”，意思就是人事僱傭我看重的是我的性別而非能力，這個想法一直困擾着我。隨之而來的開始自我懷疑：我真的是這個崗位的最佳人選嗎？還是隻是因為我是個女人？許多年來，我都認為公司僱傭我是因為我的能力最好。但如今卻發現，對那些僱主們來説，與我的能力相比，他們似乎更關注我的性別。",-1))]),e[17]||(e[17]=n('<p>我開解自己：我到底是因為什麼被僱傭並不重要，我知道我是這個職位的最佳人選而且我會用實際行動去證明。我工作很努力，達到過預期，也犯過錯，也收穫了很多，我做了一個老闆想要自己僱員做的一切事情。</p><p>但那個“多樣性僱傭”問題的陰影並未因此散去。我無法擺脱它，甚至迴避一切與之相關的話題如蛇蠍，最終意識到自己拒絕談論它意味着我能做的只有直面它。如果我繼續迴避這個問題，早晚會影響到我的工作，這是我最不希望看到的。</p><h3 id="傾訴心中的困擾" tabindex="-1">傾訴心中的困擾 <a class="header-anchor" href="#傾訴心中的困擾" aria-label="Permalink to “傾訴心中的困擾”">​</a></h3><p>直接談論多樣性和包容性這個話題有點尷尬，在進行自我剖析之前有幾個問題需要考慮：</p><ul><li>我們能夠相信我們的同事，能夠在他們面前表露脆弱嗎？</li><li>一個團隊的領導者在同事面前表露脆弱合適嗎？</li><li>如果我玩脱了呢？會不會影響我的工作？</li></ul><p>於是我和一位主管在午餐時間進行了一場小型的 Q&amp;A 會議，這位主管負責着集團很多領域，並且以正直坦率著稱。一位女同事問他，“我是因為多樣性才被招進來的嗎？”，他停下手頭工作花了很長時間和一屋子女性員工解釋了這件事，我不想複述他講話的全部內容，我只説對我觸動最大的幾句：如果你知道自己能夠勝任這個職位，並且面試很順利，那麼不必質疑招聘的結果。每個懷疑自己是因為多樣性僱傭進公司的人私下都有自己的問題，你不必重蹈他們的覆轍。</p><p>完畢。</p><p>我很希望我能由衷地説我放下這個問題了，但事實上我沒有。這問題揮之不去：萬一我就是被破格錄取的那個呢？萬一我就是多樣性僱傭的那個呢？我認識到我不能避免地反覆思考這些問題。</p><p>幾周後我和這位主管進行了一次一對一談話，在談話的末尾，我提到作為一位女性，自己很欣賞他那番對於多樣性和包容性的坦率發言。當得知領導很有交流的意願時，談論這種話題變得輕鬆許多。我也向他提出了最初的問題，“我是因為多樣性才被僱傭的嗎？”，他回答得很乾脆：“我們談論過這個問題。”談話後我意識到，我急切地想找人談論這些需要勇氣的問題，其實只是因為我需要有一個人的關心、傾聽和好言勸説。</p><p>但正因為我有展露脆弱的勇氣——去和那位主管談論我的問題——我承受我的秘密困擾的能力提高了。我覺得身輕如燕，我開始組織各種對話，主要圍繞着內隱偏見及其引起的一系列問題、怎樣增加自身的包容性和多樣性的表現等。通過這些經歷，我發現每個人對於多樣性都有不同的認識，如果我只囿於自己的秘密，我不會有機會組織參與這些精彩的對話。</p><p>我有談論內心脆弱的勇氣，我希望你也有。</p><p>我們可以談談那些影響我們領導力的秘密，這樣從任何意義上來説，我們距離成為一位開明的領導就近了一些。那麼適當示弱有幫助你成為更好的領導者嗎？</p><h3 id="作者簡介" tabindex="-1">作者簡介 <a class="header-anchor" href="#作者簡介" aria-label="Permalink to “作者簡介”">​</a></h3><p>Angela Robertson 是微軟的一名高管。她和她的團隊對社羣互助有着極大熱情，並參與開源工作。在加入微軟之前，Angela 就職於紅帽公司。</p><hr>',15)),o("p",null,[e[4]||(e[4]=t("via: ",-1)),l(a,{href:"https://opensource.com/article/17/12/how-allowing-myself-be-vulnerable-made-me-better-leader"},{default:r(()=>[...e[3]||(e[3]=[t("https://opensource.com/article/17/12/how-allowing-myself-be-vulnerable-made-me-better-leader",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=t("作者：",-1)),l(a,{href:"https://opensource.com/users/arobertson98"},{default:r(()=>[...e[5]||(e[5]=[t("Angela Robertson",-1)])]),_:1}),e[9]||(e[9]=t(" 譯者：",-1)),l(a,{href:"https://github.com/Valoniakim"},{default:r(()=>[...e[6]||(e[6]=[t("Valoniakim",-1)])]),_:1}),e[10]||(e[10]=t(" 校對：",-1)),l(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[7]||(e[7]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[13]||(e[13]=t("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[11]||(e[11]=[t("LCTT",-1)])]),_:1}),e[14]||(e[14]=t(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:r(()=>[...e[12]||(e[12]=[t("Linux中國",-1)])]),_:1}),e[15]||(e[15]=t(" 榮譽推出",-1))])])}const h=i(d,[["render",u]]);export{w as __pageData,h as default};
